custom_css:
/* =========================================
   「拾券」 · SillyTavern Theme
     作者：时鸢/M
     可二改
     禁止二传倒卖 =========================================

   ◆ 换色：修改下方 :root 变量即可全局换色
   ◆ 换图：修改 --sq-banner-xxx 的 URL
   ========================================= */

:root {

  /* ═══════════════════════════════════════
     🎨 换色区 — 改这里换整套配色
     ═══════════════════════════════════════ */

  --sq-deep:    #3a3530;   /* 碳墨 — 标题、正文强调 */
  --sq-mid:     #b8a080;   /* 暗金 — 边框、线条、hover */
  --sq-soft:    #9a8e7e;   /* 柔金 — 次要图标、placeholder */
  --sq-light:   #c8bfb0;   /* 浅暖 — 楼层号、计时器 */
  --sq-muted:   #8c7350;   /* 深金 — 行内代码、斜体 */
  --sq-warm:    #645a4b;   /* 墨棕 — 选中文本底色 */

  --sq-cream:   #fdfbf7;   /* 奶白 — 代码块、卡片 */
  --sq-page:    #f5f2ed;   /* 纸色 — 页面底色 */
  --sq-text:    #23211e;   /* 正文 — 主要文字 */
  --sq-select:  #fcf6eb;   /* 选中 — 文字选中亮色 */


  /* ═══════════════════════════════════════
     🖼️ 换图区 — 改 URL 换图片
     ═══════════════════════════════════════ */

  --sq-banner-bot:  url("https://iili.io/qEoxJzN.jpg");   /* 角色 banner */
  --sq-banner-user: url("https://iili.io/qEoxJzN.jpg");   /* 用户 banner */
  --sq-mask-bot:    url("https://iili.io/q0ggOyN.png");   /* 角色票根蒙版 */
  --sq-mask-user:   url("https://iili.io/q0hYVMg.png");   /* 用户票根蒙版 */
  --sq-ticket-bg:   #3a3530;                               /* 票根底色 */

/* ═══════════════════════════════════════
     ✏️ 文案区 — 改这里换显示文字
     ═══════════════════════════════════════ */

  --sq-thinking:       "「 片刻沉吟 · · · 」";   /* 思维链收起时 */
  --sq-placeholder:    "此 处 留 白 ···";          /* 输入框占位符 */


  /* ═══════════════════════════════════════
     🔔 功能色 — Toast 通知
     ═══════════════════════════════════════ */

  --sq-success:    #6b8e6b;
  --sq-error:      #bf616a;
  --sq-error-dark: #a65353;
  --sq-warning:    #c48b52;
  --sq-info:       #6c859e;


  /* ═══════════════════════════════════════
     ⚙️ 半透明色阶（跟随主色，一般不用改）
     ═══════════════════════════════════════ */

  --sq-mid-90: rgba(184, 160, 128, 0.9);
  --sq-mid-60: rgba(184, 160, 128, 0.6);
  --sq-mid-50: rgba(184, 160, 128, 0.5);
  --sq-mid-40: rgba(184, 160, 128, 0.4);
  --sq-mid-35: rgba(184, 160, 128, 0.35);
  --sq-mid-30: rgba(184, 160, 128, 0.3);
  --sq-mid-25: rgba(184, 160, 128, 0.25);
  --sq-mid-20: rgba(184, 160, 128, 0.2);
  --sq-mid-15: rgba(184, 160, 128, 0.15);
  --sq-mid-12: rgba(184, 160, 128, 0.12);
  --sq-mid-10: rgba(184, 160, 128, 0.1);

  --sq-page-95: rgba(245, 242, 237, 0.95);
  --sq-page-90: rgba(245, 242, 237, 0.9);
  --sq-page-75: rgba(245, 242, 237, 0.75);
  --sq-page-35: rgba(245, 242, 237, 0.35);
  --sq-page-20: rgba(245, 242, 237, 0.2);
  --sq-page-10: rgba(245, 242, 237, 0.1);
  --sq-page-05: rgba(245, 242, 237, 0.05);

  --sq-card-60: rgba(250, 247, 240, 0.6);
  --sq-card-50: rgba(250, 247, 240, 0.5);
  --sq-card-30: rgba(250, 247, 240, 0.3);

  --sq-ink-05: rgba(40, 30, 20, 0.05);
  --sq-ink-04: rgba(40, 30, 20, 0.04);
  --sq-ink-08: rgba(60, 50, 40, 0.08);
}

/* 全局字体 */
@import url("https://fontsapi.zeoseven.com/2/main/result.css");
@import url('https://fonts.googleapis.com/css2?family=Great+Vibes&display=swap');

body {
font-family: "LXGW ZhenKai GB";
font-weight: normal;
}

/* ═══════════════════════════════════════
   1. 全局基础
   ═══════════════════════════════════════ */

/* 去阴影 */
body *,
body *::before,
body *::after {
  text-shadow: none !important;
  box-shadow: none !important;
  filter: none !important;
}

/* ----- 顶栏缩小30% + 配色 ----- */



/* 顶栏图标缩小30% + 换色 */
.drawer-icon {
  font-size: calc(1em * 1.1) !important;
  color: var(--sq-soft) !important;
  -webkit-text-fill-color: var(--sq-soft) !important;
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
}

.drawer-icon:hover {
  color: var(--sq-mid) !important;
  -webkit-text-fill-color: var(--sq-mid) !important;
}

#options_button,
#extensionsMenuButton {
  background: none !important;
}



/* ----- 正文滚动条隐藏 ----- */
#chat {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

#chat::-webkit-scrollbar {
  display: none !important;
}

/* ----- 其他区域滚动条 ----- */
::-webkit-scrollbar {
  width: 3px !important;
}

::-webkit-scrollbar-track {
  background: transparent !important;
}

::-webkit-scrollbar-thumb {
  background: var(--sq-light) !important;
  border-radius: 2px !important;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--sq-mid) !important;
}

/* 正文 */
.mes_block {
  flex: 1 !important;
  min-width: 0 !important;
  overflow: visible !important;
  position: relative !important;
}

.mes_text {
  width: calc(100% + 30px) !important;
  max-width: calc(100% + 205px) !important;
  margin-left: 0px !important;
  margin-top: 40px !important;
}


/* ----- mes_block 定位参考 ----- */
.mes .mes_block {
  position: relative !important;
}

/* ----- 票根外壳：角色消息 ----- */
.mes[is_user="false"] .mes_block::before {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  aspect-ratio: 2.3 / 1 !important;
  position: relative !important;
  background: var(--sq-deep) !important;
  -webkit-mask-image: var(--sq-mask-bot) !important;
  -webkit-mask-size: 100% 100% !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-image: var(--sq-mask-bot) !important;
  mask-size: 100% 100% !important;
  mask-repeat: no-repeat !important;
}

/* ----- 票根外壳：用户消息 ----- */
.mes[is_user="true"] .mes_block::before {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  aspect-ratio: 2.3 / 1 !important;
  position: relative !important;
  background: var(--sq-deep) !important;
  -webkit-mask-image: var(--sq-mask-user) !important;
  -webkit-mask-size: 100% 100% !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-image: var(--sq-mask-user) !important;
  mask-size: 100% 100% !important;
  mask-repeat: no-repeat !important;
}

/* ----- 角色头像 → 左侧 ----- */
.mes[is_user="false"] .mesAvatarWrapper {
  position: absolute !important;
  left: calc(10%) !important;
  top: calc(15px) !important;
  z-index: 10 !important;
  overflow: visible !important;
}

/* ----- 用户头像 → 右侧 ----- */
.mes[is_user="true"] .mesAvatarWrapper {
  position: absolute !important;
  right: calc(6.5%) !important;
  top: calc(15px) !important;
  z-index: 10 !important;
  overflow: visible !important;
}

/* ----- 头像圆形 ----- */
.mes .avatar {
  width: calc(55px) !important;
  height: calc(55px) !important;
  overflow: hidden !important;
  border-radius: 50% !important;
}

.mes .avatar img {
  width: 100% !important;
  height: 100% !important;
  border-radius: 50% !important;
  border: 2px solid var(--sq-mid) !important;
  object-fit: cover !important;
}


/* ----- 角色背景图 → 从头像往右延伸 ----- */
.mes[is_user="false"] .mesAvatarWrapper::after {
  content: "" !important;
  position: absolute !important;
  left: calc(100% + 38px) !important;
  top: 68.5% !important;
  transform: translateY(-67.5%) !important;
  width: calc(55vw) !important;
  aspect-ratio: 2.2 / 1 !important;
  background: var(--sq-banner-bot) center center / cover no-repeat !important;
  border-radius: calc(8px) !important;
  pointer-events: none !important;
}

/* ----- 用户背景图 → 从头像往左延伸 ----- */
.mes[is_user="true"] .mesAvatarWrapper::after {
  content: "" !important;
  position: absolute !important;
  right: calc(100% + 40px) !important;
  top: 59% !important;
  transform: translateY(-50%) !important;
  width: calc(55vw) !important;
  aspect-ratio: 2.2 / 1 !important;
  background: var(--sq-banner-user) center center / cover no-repeat !important;
  border-radius: calc(8px) !important;
  pointer-events: none !important;
}


/* ----- 首条消息单独修正 ----- */
.mes[mesid="0"] .mesAvatarWrapper {
  top: calc(35px) !important;
}

.mes[mesid="0"] .mes_block::before {
  margin-top: 0 !important;
}

/* ----- 最后一条消息修正 ----- */
.mes.last_mes .mes_block::before {
  margin-top: 0 !important;
  padding-top: 0 !important;
}

.mes.last_mes .mesAvatarWrapper {
  top: calc(15px) !important;
}
/* ----- 最后一条消息背景图上移 ----- */
.mes.last_mes .mesAvatarWrapper::after {
  top: calc(45%) !important;
}


/* ----- 楼层 + 字符 + 计时器浅色 ----- */
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
  color: var(--sq-light) !important;
}


/* ----- 名字 + 时间戳浅色 ----- */
.name_text {
  color: var(--sq-light) !important;
}

.timestamp {
  color: var(--sq-light) !important;
}

/* ----- 角色名字位置 ----- */
.mes[is_user="false"] .name_text {
  position: relative !important;
  left: calc(108px) !important;
  top: calc(-31px) !important;
}

/* ----- 角色时间戳位置 ----- */
.mes[is_user="false"] .timestamp {
  position: absolute !important;
  left: calc(220px) !important;
  top: calc(117px) !important;
}

/* ----- 用户名字位置 ----- */
.mes[is_user="true"] .name_text {
  position: relative !important;
  left: calc(25px) !important;
  top: calc(-30px) !important;
}

/* ----- 用户时间戳固定位置 ----- */
.mes[is_user="true"] .timestamp {
  position: absolute !important;
  right: calc(110px) !important;
  top: calc(117px) !important;
}



/* ----- 角色楼层位置 ----- */
.mes[is_user="false"] .mesIDDisplay {
  position: relative !important;
  left: calc(0px) !important;
  top: calc(10px) !important;
}

/* ----- 角色计时器位置 ----- */
.mes[is_user="false"] .mes_timer {
  position: relative !important;
  left: calc(0px) !important;
  top: calc(15px) !important;
}

/* ----- 角色字符数位置 ----- */
.mes[is_user="false"] .tokenCounterDisplay {
  position: relative !important;
  left: calc(0px) !important;
  top: calc(20px) !important;
}

/* ----- 用户楼层位置 ----- */
.mes[is_user="true"] .mesIDDisplay {
  position: relative !important;
  left: calc(0px) !important;
  top: calc(10px) !important;
}

/* ----- 用户计时器位置 ----- */
.mes[is_user="true"] .mes_timer {
  position: relative !important;
  left: calc(0px) !important;
  top: calc(0px) !important;
}

/* ----- 用户字符数位置 ----- */
.mes[is_user="true"] .tokenCounterDisplay {
  position: relative !important;
  left: calc(0px) !important;
  top: calc(30px) !important;
}

/* ----- 幽灵图标浅色 ----- */
.mes_ghost.fa-ghost {
  color: var(--sq-light) !important;
}

/* ----- 角色幽灵位置 ----- */
.mes[is_user="false"] .mes_ghost.fa-ghost {
  position: relative !important;
  left: calc(110px) !important;
  top: calc(-30px) !important;
}

/* ----- 用户幽灵位置 ----- */
.mes[is_user="true"] .mes_ghost.fa-ghost {
  position: relative !important;
  left: calc(30px) !important;
  top: calc(-30px) !important;
}


/* ----- 复选框 (Checkbox) 限定作用域美化 ----- */
.checkbox_label input[type="checkbox"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 15px !important;
  height: 15px !important;
  border: 1.5px solid var(--sq-mid) !important;
  border-radius: 50% !important; 
  background-color: transparent !important;
  cursor: pointer !important;
  position: relative !important;
  top: 5px !important; /* 对齐文本 */
  display: inline-block !important;
  vertical-align: middle !important;
  transition: all 0.2s ease-in-out !important;
  box-shadow: none !important;
}

/* 鼠标悬浮时的反馈 */
.checkbox_label input[type="checkbox"]:hover {
  background-color: var(--sq-mid-15) !important;
}

/* 选中状态 */
.checkbox_label input[type="checkbox"]:checked {
  background-color: var(--sq-deep) !important; 
  border-color: var(--sq-deep) !important;
}

/* 绘制对勾 */
.checkbox_label input[type="checkbox"]:checked::after {
  content: '' !important;
  position: absolute !important;
  top: 1px !important;
  left: 3.5px !important;
  width: 3.5px !important;
  height: 7px !important;
  border: solid var(--sq-mid) !important; 
  border-width: 0 2px 2px 0 !important;
  transform: rotate(45deg) !important;
}


/* =========================================
   设置面板 UI 美化 (限定作用域版)
   ========================================= */

/* ----- 1. 标题栏去灰色渐变 ----- */
#right-nav-panel .inline-drawer-header,
#left-nav-panel .inline-drawer-header,
.drawer-content .inline-drawer-header,
.drawer-content .title_restorable {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  border-bottom: 1.5px solid var(--sq-mid-50) !important;
  border-radius: 0 !important;
  color: var(--sq-deep) !important;
}

/* 设置项去灰底 */
.drawer-content .list-group-item,
.drawer-content .setting_block {
  background-color: transparent !important;
  background-image: none !important;
}

/* ----- 2. 输入框、下拉菜单、按钮 ----- */
.drawer-content select,
.drawer-content input[type="text"],
.drawer-content input[type="number"],
.drawer-content input[type="search"],
.drawer-content .text_pole,
.drawer-content .menu_button,
.drawer-content .menu_button_icon {
  background-color: var(--sq-mid-15) !important;
  border: none !important;
  border-radius: calc(4px) !important;
  color: var(--sq-deep) !important;
  transition: background-color 0.2s ease !important;
}

/* 悬停/聚焦 */
.drawer-content select:hover,
.drawer-content input[type="text"]:focus,
.drawer-content input[type="number"]:focus,
.drawer-content .menu_button:hover,
.drawer-content .menu_button_icon:hover {
  background-color: var(--sq-mid-25) !important;
  outline: none !important;
}

/* ----- 3. 滑块 ----- */
.drawer-content input[type="range"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  background: transparent !important;
}

.drawer-content input[type="range"]::-webkit-slider-runnable-track {
  height: calc(3px) !important;
  background: var(--sq-mid-40) !important;
  border-radius: calc(2px) !important;
  border: none !important;
}

.drawer-content input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  height: calc(14px) !important;
  width: calc(14px) !important;
  border-radius: 50% !important;
  background: var(--sq-deep) !important;
  border: 1.5px solid var(--sq-mid) !important;
  margin-top: calc(-5.5px) !important;
  cursor: pointer !important;
  transition: transform 0.2s ease !important;
}

.drawer-content input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.2) !important;
  background: var(--sq-mid) !important;
  border-color: var(--sq-deep) !important;
}


/* =========================================
   正文附加组件美化：思维链 (古典留白重制版)
   ========================================= */

/* ----- 1. 彻底隐藏烦人的原生下拉箭头 ----- */
#chat .mes_reasoning_header {
  list-style: none !important; 
}
#chat .mes_reasoning_header::-webkit-details-marker {
  display: none !important; 
}

/* ----- 2. 隐藏原有枯燥文字，重塑基础样式 ----- */
#chat .mes_reasoning_header {
  font-size: 0 !important; /* 将原本的文字缩小为0以隐藏 */
  background-color: transparent !important;
  border: none !important; /* 抛弃所有边框 */
  box-shadow: none !important;
  padding: 4px 0 !important;
  cursor: pointer !important;
  transition: all 0.3s ease !important;
  display: inline-flex !important;
  align-items: center !important;
}

/* ----- 3. 注入文艺文案与排版样式 ----- */
#chat .mes_reasoning_header::before {
  content: var(--sq-thinking) !important;
  font-size: 13px !important; /* 恢复我们自己注入的字号 */
  font-family: "NanoOldSong-A", "宋体", serif !important; /* 强制使用主题的旧宋体 */
  color: var(--sq-soft) !important; /* 柔和的墨色 */
  letter-spacing: 2px !important; /* 增加字间距，更显呼吸感 */
  transition: all 0.3s ease !important;
}

/* 鼠标悬停时的优雅反馈 */
#chat .mes_reasoning_header:hover::before {
  color: var(--sq-mid) !important; /* 变为主题暗金 */
  text-shadow: 0 0 8px var(--sq-mid-30) !important; /* 极其微弱的发光，像墨迹微湿 */
}



/* 展开的主体文本框：去除死板的底色，改为极简的左侧引线 */
#chat .mes_reasoning {
  background: transparent !important;
  border: none !important;
  border-left: 1.5px solid var(--sq-mid-30) !important; 
  color: var(--sq-soft) !important;
  padding-left: 14px !important;
  margin-left: 4px !important;
  margin-top: 8px !important;
  font-size: 0.95em !important;
}

/* ----- 彻底隐藏 ST 自定义的下拉小箭头 ----- */
#chat .mes_reasoning_arrow {
  display: none !important;
}


/* =========================================
   编辑栏按钮美化 (三个点/星星/铅笔)
   ========================================= */

/* ----- 按钮容器 ----- */
.mes_buttons {
  display: flex !important;
  align-items: center !important;
  gap: calc(6px) !important;
}

/* ----- 所有按钮统一基础样式 ----- */
.mes_buttons .mes_button,
.mes_buttons .extraMesButtons {
  color: var(--sq-light) !important;
  background: transparent !important;
  border: none !important;
  font-size: calc(1em * 0.85) !important;
  opacity: 0.5 !important;
  transition: all 0.25s ease !important;
  cursor: pointer !important;
}

/* 悬停：渐显 + 变暗金 */
.mes_buttons .mes_button:hover,
.mes_buttons .extraMesButtons:hover {
  opacity: 1 !important;
  color: var(--sq-mid) !important;
}

/* ----- 收藏星星选中态 ----- */
.mes_buttons .mes_bookmark.fav_on,
.mes_buttons .bookmark_link.fav_on {
  opacity: 1 !important;
  color: var(--sq-mid) !important;
}

/* ----- 鼠标没悬停在消息上时隐藏按钮 ----- */
.mes .mes_buttons {
  opacity: 0 !important;
  transition: opacity 0.3s ease !important;
}

.mes:hover .mes_buttons {
  opacity: 1 !important;
}

/* ----- 编辑栏位置下移 + 颜色加深 ----- */
.mes_buttons .mes_button,
.mes_buttons .extraMesButtons {
  opacity: 0.7 !important;
  color: var(--sq-mid) !important;
}


/* ----- 编辑栏和思维链同行 (绝对定位脱离文档流 + 顶层显示) ----- */
.mes .mes_buttons {
  position: absolute !important; 
  top: calc(100vw / 3 + 45px) !important;   /* 关键：配合正文的下移，刚好落在思维链所在的水平线上 */
  right: 10px !important; /* 靠右侧边缘，可微调 */
  z-index: 20 !important; /* 提高层级，绝对防止被票根背景图或底色遮挡 */
  display: inline-flex !important;
  gap: 8px !important;
  margin: 0 !important;   /* 清除干扰的 margin */
}

/* 确保父容器是相对定位 */
.mes .mes_block {
  position: relative !important;
}


/* ----- 思维链编辑按钮颜色 ----- */
.mes_reasoning_actions .mes_button {
  color: var(--sq-mid) !important;
  -webkit-text-fill-color: var(--sq-mid) !important;
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  opacity: 0.6 !important;
  border: none !important;
  transition: all 0.25s ease !important;
}

.mes_reasoning_actions .mes_button:hover {
  opacity: 1 !important;
}

/* ----- 思维链编辑按钮位置微调 ----- */
.mes_reasoning_actions {
  position: relative !important;
  top: calc(20px) !important;
  right: calc(13px) !important;
}

/* ----- 编辑模式文本区 ----- */
.mes .mes_text textarea,
.mes .mes_edit_textarea {
  background: var(--sq-page-95) !important;
  color: var(--sq-deep) !important;
  border: 1px solid var(--sq-mid) !important;
  border-radius: calc(4px) !important;
  font-family: "NanoOldSong-A", "宋体", serif !important;
}

/* ----- 标题栏去灰 ----- */
.inline-drawer-header,
.drawer-content h4,
.drawer-content .title_restorable,
.panel-heading,
.inline-drawer-header b {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  border-radius: 0 !important;
  color: var(--sq-deep) !important;
}

/* 只给最外层标题加底线 */
.inline-drawer-header {
  border-bottom: 1.5px solid var(--sq-mid-50) !important;
}

/* ----- 思维链编辑文本区 ----- */
.reasoning_edit_textarea {
  background: var(--sq-page-95) !important;
  color: var(--sq-deep) !important;
  border: 1px solid var(--sq-mid-40) !important;
  border-radius: calc(4px) !important;
  font-family: "NanoOldSong-A", "宋体", serif !important;
}


/* =========================================
   编辑模式按钮栏美化 (悬浮弹性适配 + 修复常驻Bug)
   ========================================= */
#chat .mes_edit_buttons {
  /* 【关键修复】：绝对不能写 display 属性，让 ST 系统自己控制显隐！ */
  position: absolute !important; /* 悬浮脱离文档流，绝不挤压思维链 */
  top: calc(12rem) !important;  /* 使用 rem 相对单位，温柔适配手机/电脑双端 */
  right: calc(-1.5rem) !important; /* 靠右边距随屏幕动态伸缩 */
  z-index: 30 !important; /* 保证悬浮在最上层 */
  gap: calc(0.4rem) !important;
}

/* 统一按钮的基础样式，去除原版红绿大色块 */
#chat .mes_edit_buttons .menu_button,
#chat .mes_edit_buttons button {
  background-color: var(--sq-page-95) !important; 
  border: 1.5px solid var(--sq-mid-40) !important; 
  color: var(--sq-soft) !important;
  border-radius: calc(0.3rem) !important; 
  padding: calc(0.3rem) calc(0.6rem) !important; 
  box-shadow: none !important;
  transition: all 0.2s ease !important;
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
}

/* 清除确认/取消按钮强加的背景图 */
#chat .mes_edit_buttons .mes_edit_done,
#chat .mes_edit_buttons .mes_edit_cancel {
  background-image: none !important; 
}

/* 悬停状态：反相填充暗金色 */
#chat .mes_edit_buttons .menu_button:hover,
#chat .mes_edit_buttons button:hover {
  background-color: var(--sq-mid) !important;
  color: var(--sq-deep) !important; 
  border-color: var(--sq-mid) !important;
}


/* ----- 思维链编辑按钮：无框纯图标风格 ----- */
.mes_reasoning_actions .menu_button,
.mes_reasoning_actions .edit_button,
.mes_reasoning_edit_done,
.mes_reasoning_edit_cancel {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  color: var(--sq-light) !important;
  -webkit-text-fill-color: var(--sq-light) !important;
  font-size: calc(1em * 0.82) !important;
  padding: calc(4px) calc(6px) !important;
  min-width: unset !important;
  min-height: unset !important;
  width: auto !important;
  height: auto !important;
  transform: none !important;
  transition: all 0.25s ease !important;
  cursor: pointer !important;
  line-height: 1 !important;
}

.mes_reasoning_actions .menu_button:hover,
.mes_reasoning_actions .edit_button:hover,
.mes_reasoning_edit_done:hover,
.mes_reasoning_edit_cancel:hover {
  color: var(--sq-mid) !important;
  -webkit-text-fill-color: var(--sq-mid) !important;
  background: transparent !important;
}

/* =========================================
   思维链编辑面板：整体下移避让按钮 (修复常驻Bug)
   ========================================= */
#chat .reasoning_edit_textarea {
  position: relative !important;
  margin-top: calc(0.8rem) !important; /* 温柔下移，避开右上角图标 */
}

/* 【关键修复 1】：未展开时，严格隐藏操作图标 */
#chat details:not([open]) .mes_reasoning_actions {
  display: none !important;
}

/* 【关键修复 2】：只有展开时，才显示图标并应用间距排版 */
#chat details[open] .mes_reasoning_actions {
  display: inline-flex !important;
  align-items: center !important;
  margin-left: calc(0.5rem) !important;
  gap: calc(0.4rem) !important;
}




/* ----- 消息间距拉大 50px ----- */
#chat .mes {
  margin-bottom: 50px !important; /* 给每条消息底部强行撑开 50px 的空间 */
}


/* ----- 引用文本 (对话内容，通常在双引号或 <q> 标签内) ----- */
.mes_text q {
  color: var(--sq-warm) !important; /* 比正文稍微深一点的墨色，增加阅读层次感 */
  /* font-weight: bold !important; */ /* 如果你想让对话加粗，可以把这行最前面的 /* 删掉 */
}

/* ----- 斜体文本 (*斜体*) ----- */
.mes_text em,
.mes_text i {
  color: var(--sq-muted) !important; /* 使用了你主题原本的下划线颜色 */
  font-style: italic !important;
  border-bottom: 1px dashed var(--sq-mid-50) !important; /* 加一条极淡的暗金虚线底边，非常有手账感 */
  padding-bottom: 1px !important;
}

/* ----- 块级引用 (> 文本) ----- */
.mes_text blockquote {
  background: var(--sq-mid-10) !important; /* 极淡的暗金色背景 */
  border-left: 3px solid var(--sq-mid) !important;       /* 左侧暗金提示线 */
  padding: 8px 14px !important;
  margin: 12px 0 !important;
  border-radius: 0 4px 4px 0 !important;           /* 右侧微圆角，左侧直角贴线 */
  color: var(--sq-warm) !important;
  font-size: 0.95em !important;
}

/* ----- 代码块样式 (行内与独立代码块) ----- */

/* 行内代码 (被单反引号 ` 包裹的文字) */
.mes_text code:not(pre code) {
  background-color: var(--sq-mid-15) !important;
  color: var(--sq-deep) !important;
  padding: 2px 6px !important;
  border-radius: 4px !important;
  border: 1px solid var(--sq-mid-30) !important; /* 细细的暗金框 */
  font-size: 0.9em !important;
}


/* =========================================
   正文排版精修：高阶质感与纯 CSS 票根
   ========================================= */


/* ----- 独立代码块：纯 CSS 拟真票根形态 ----- */
.mes pre {
  position: relative !important;
  background-color: transparent !important; 
  /* 核心魔法：使用径向渐变在左右两侧“挖”出半圆形的缺口 */
  background-image: 
    radial-gradient(circle at 0 50%, transparent 8px, var(--sq-cream) 9px),
    radial-gradient(circle at 100% 50%, transparent 8px, var(--sq-cream) 9px) !important;
  background-size: 51% 100% !important;
  background-position: left, right !important;
  background-repeat: no-repeat !important;

  color: var(--sq-deep) !important;
  padding: 18px 20px 18px 40px !important; /* 左侧留出打孔线的空间 */
  margin: 20px 0 !important;
  border: none !important; /* 必须去掉边框，否则掏空效果会穿帮 */
  border-radius: 6px !important;

  /* 魔法阴影：box-shadow无法识别透明缺口，必须用 filter: drop-shadow 完美贴合边缘 */
  filter: drop-shadow(0px 3px 6px var(--sq-mid-15)) !important;
  overflow: visible !important; /* 允许阴影和内部元素正常显示 */
}

/* 票根内侧的撕裂虚线 (模拟打孔存根) */
.mes pre::before {
  content: "" !important;
  position: absolute !important;
  top: 12px !important;
  bottom: 12px !important;
  left: 20px !important; /* 定位在左侧缺口内侧 */
  width: 0 !important;
  border-left: 1.5px dashed var(--sq-mid-40) !important;
  pointer-events: none !important;
}

/* 修复代码错位问题 */
.mes pre code {
  background: transparent !important;
  color: var(--sq-warm) !important;
  border: none !important;
  padding: 0 !important;
  margin: 0 !important;
  display: block !important;
  overflow-x: auto !important; /* 内容过长时允许横向滚动，但不破坏票根外壳 */
  line-height: 1.5 !important;
}

/* 行内代码保持克制 */
.mes_text code:not(pre code) {
  background-color: var(--sq-mid-12) !important;
  color: var(--sq-muted) !important;
  padding: 2px 6px !important;
  border-radius: 4px !important;
  border: 1px solid var(--sq-mid-20) !important;
}

/* ----- 选中文本：浓郁复古墨棕 + 亮奶金字 ----- */
::selection {
  background-color: var(--sq-warm) !important; 
  color: var(--sq-select) !important;  /* 极亮的奶金/米白色，极大提升高级感和对比度 */
}
::-moz-selection {
  background-color: var(--sq-warm) !important;
  color: var(--sq-select) !important;
}


/* 方案三：半高亮荧光笔 (极简手账风) */
.mes_text q {
  color: var(--sq-warm) !important;
  quotes: none !important; /* 彻底移除多余引号 */
  /* 用背景渐变做到“只高亮下半部分”的荧光笔效果 */
  background: linear-gradient(to top, var(--sq-mid-25) 35%, transparent 35%) !important;
  padding: 0 2px !important;
}
.mes_text q::before, .mes_text q::after { content: none !important; }

/* ----- 下拉箭头：收起状态 ----- */
.inline-drawer-icon.fa-circle-chevron-down {
  font-size: 0 !important;
  background: none !important;
  border: none !important;
  width: calc(24px) !important;
  height: calc(24px) !important;
  position: relative !important;
}

.inline-drawer-icon.fa-circle-chevron-down::before {
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900 !important;
  content: "\f078" !important;
  font-size: calc(12px) !important;
  color: var(--sq-mid) !important;
  -webkit-text-fill-color: var(--sq-mid) !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  transition: all 0.3s ease !important;
}

.inline-drawer-icon.fa-circle-chevron-down:hover::before {
  color: var(--sq-deep) !important;
  -webkit-text-fill-color: var(--sq-deep) !important;
}

/* ----- 下拉箭头展开状态 ----- */
.inline-drawer-icon.fa-circle-chevron-up {
  font-size: 0 !important;
  background: none !important;
  border: none !important;
  width: calc(24px) !important;
  height: calc(24px) !important;
  position: relative !important;
}

.inline-drawer-icon.fa-circle-chevron-up::before {
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900 !important;
  content: "\f077" !important;
  font-size: calc(12px) !important;
  color: var(--sq-mid) !important;
  -webkit-text-fill-color: var(--sq-mid) !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
}

.inline-drawer-icon.fa-circle-chevron-up:hover::before {
  color: var(--sq-deep) !important;
  -webkit-text-fill-color: var(--sq-deep) !important;
}


/* =========================================
   预设条目美化
   ========================================= */

/* ----- 面板背景去色（关键：覆盖CSS变量） ----- */
.range-block.pt-entry-grouping-root,
.range-block.pt-entry-grouping-root * {
  --pt-bg: transparent !important;
  --pt-section-bg: transparent !important;
  --pt-border: var(--sq-mid-30) !important;
  --pt-text: var(--sq-deep) !important;
  --pt-tip: var(--sq-soft) !important;
}

.range-block.pt-entry-grouping-root {
  background: transparent !important;
  color: var(--sq-deep) !important;
}

#completion_prompt_manager_list {
  background: transparent !important;
  border: none !important;
}

#completion_prompt_manager .pt-entry-grouping-root {
  background: transparent !important;
}

.completion_prompt_manager_list_separator,
.completion_prompt_manager_list_head {
  background: transparent !important;
  color: var(--sq-deep) !important;
}

/* ----- 顶部标题栏文字 ----- */
#completion_prompt_manager span,
#completion_prompt_manager b,
#completion_prompt_manager label,
.prompt_manager_header_advanced span,
.prompt_manager_header_advanced b,
.prompt_manager_prompt_list_header span {
  color: var(--sq-deep) !important;
  -webkit-text-fill-color: var(--sq-deep) !important;
}

/* ----- 条目基础：虚线 ----- */
#completion_prompt_manager .completion_prompt_manager_prompt {
  background: transparent !important;
  border: 2px dashed var(--sq-mid-40) !important;
  border-radius: calc(6px) !important;
  transition: all 0.25s ease !important;
}

/* ----- 启用条目：实线 + 暖底 ----- */
#completion_prompt_manager .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
  border: 2px solid var(--sq-mid) !important;
  background: var(--sq-card-50) !important;
}

/* ----- 启用条目文字：主题深色（不是纯黑） ----- */
#completion_prompt_manager .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt_manager_prompt_name,
#completion_prompt_manager .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt_manager_prompt_tokens,
#completion_prompt_manager .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) > span {
  color: var(--sq-deep) !important;
  -webkit-text-fill-color: var(--sq-deep) !important;
}

/* ----- 禁用条目：降饱和 ----- */
#completion_prompt_manager .completion_prompt_manager_prompt_disabled {
  opacity: 0.55 !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt_disabled .prompt_manager_prompt_name,
#completion_prompt_manager .completion_prompt_manager_prompt_disabled .prompt_manager_prompt_tokens,
#completion_prompt_manager .completion_prompt_manager_prompt_disabled > span {
  color: var(--sq-mid) !important;
  -webkit-text-fill-color: var(--sq-mid) !important;
}

/* ----- 悬停 ----- */
#completion_prompt_manager .completion_prompt_manager_prompt:hover {
  border-color: var(--sq-mid) !important;
  background: var(--sq-card-30) !important;
  opacity: 1 !important;
}

/* ----- 条目图标按钮：暗金 ----- */
.prompt-manager-detach-action,
.prompt-manager-edit-action,
.prompt-manager-toggle-action,
.fa-chain-broken,
.fa-toggle-off,
.fa-toggle-on,
.prompt_manager_prompt_controls .fa-solid,
.prompt_manager_prompt_controls .fa-pencil,
.prompt_manager_prompt_controls span {
  color: var(--sq-mid) !important;
  -webkit-text-fill-color: var(--sq-mid) !important;
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  text-shadow: none !important;
  filter: none !important;
}

.prompt-manager-detach-action:hover,
.prompt-manager-edit-action:hover,
.prompt-manager-toggle-action:hover {
  color: var(--sq-deep) !important;
  -webkit-text-fill-color: var(--sq-deep) !important;
}

/* ----- Toggle 开关图标 ----- */
.fa-toggle-on,
.fa-toggle-off {
  font-size: calc(1.1em) !important;
  background: linear-gradient(to bottom, var(--sq-muted), var(--sq-mid)) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
}

/* =========================================
   底栏输入框
   ========================================= */

/* ----- 底栏整体布局 ----- */



/* ----- 外框去边框 ----- */
#send_form {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  display: flex !important;
  align-items: center !important;
}

/* ----- 输入框 ----- */
#send_textarea {
  background: transparent !important;
  border: none !important;
  color: var(--sq-text) !important;
  font-family: "NanoOldSong-A", "宋体", serif !important;
}

#send_textarea:focus {
  outline: none !important;
  border-color: var(--sq-mid) !important;
}

/* ----- placeholder 隐藏原文 + 注入文案 ----- */
#send_textarea::placeholder {
  color: transparent !important;
}

#send_textarea:placeholder-shown + .placeholder-text,
#send_form:has(#send_textarea:placeholder-shown)::after {
  content: none !important;
}

#nonQRFormItems {
  position: relative !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::after {
  content: var(--sq-placeholder) !important;
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  font-size: calc(0.5em) !important;
  font-family: "LXGW ZhenKai GB", serif !important;
  color: var(--sq-mid-40) !important;
  pointer-events: none !important;
  letter-spacing: calc(2px) !important;
  white-space: nowrap !important;
}

#nonQRFormItems:has(#send_textarea:focus)::after,
#nonQRFormItems:has(#send_textarea:not(:placeholder-shown))::after {
  display: none !important;
}

/* ----- 底栏图标 ----- */
#send_form .fa-solid {
  background: none !important;
  transform: scale(0.7) !important;
}

#send_form .fa-solid::before {
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  -webkit-text-fill-color: var(--sq-soft) !important;
  color: var(--sq-soft) !important;
}


/* =========================================
   预设管理列表 (Prompt Manager) 色彩定制 (F12精确版)
   ========================================= */

/* ----- 1. 开启状态：标题与字符数 (深碳墨色) ----- */
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .completion_prompt_manager_prompt_name,
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt_manager_prompt_tokens {
  color: var(--sq-deep) !important; /* 去除纯黑，换成主题复古深色 */
}

/* ----- 2. 开启状态：操作图标 (铅笔、取消链接) ----- */
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt_manager_prompt_controls span,
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt_manager_prompt_controls span::before {
  color: var(--sq-muted) !important; /* 温润深暗金 */
  -webkit-text-fill-color: var(--sq-muted) !important; /* 彻底覆盖任何可能残留的透明遮罩 */
  transition: color 0.2s ease !important;
}

/* 开启状态：单独高亮开关按钮 (Toggle On) */
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action,
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action::before {
  color: var(--sq-mid) !important; 
  -webkit-text-fill-color: var(--sq-mid) !important;
}

/* 开启状态：图标悬停效果 */
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt_manager_prompt_controls span:hover,
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt_manager_prompt_controls span:hover::before {
  color: var(--sq-deep) !important; /* 悬停变为深墨色 */
  -webkit-text-fill-color: var(--sq-deep) !important;
}

/* ----- 3. 关闭状态：仅修改操作图标 (半透明暗金) ----- */
/* 标题和字符数会自动继承 ST 的灰色，不碰它们 */
li.completion_prompt_manager_prompt_disabled .prompt_manager_prompt_controls span,
li.completion_prompt_manager_prompt_disabled .prompt_manager_prompt_controls span::before {
  color: var(--sq-mid-50) !important; /* 半透明淡暗金 */
  -webkit-text-fill-color: var(--sq-mid-50) !important;
  transition: color 0.2s ease !important;
}

/* 关闭状态：图标悬停效果 */
li.completion_prompt_manager_prompt_disabled .prompt_manager_prompt_controls span:hover,
li.completion_prompt_manager_prompt_disabled .prompt_manager_prompt_controls span:hover::before {
  color: var(--sq-mid) !important; 
  -webkit-text-fill-color: var(--sq-mid) !important;
}



/* =========================================
   正文消息气泡 (极简通透流：抛弃边框，释放呼吸感)
   ========================================= */

#chat .mes {
  /* 几乎全透的底色，纯靠毛玻璃和背景图融合 */
  background-color: var(--sq-page-05) !important; 
  backdrop-filter: blur(25px) saturate(120%) !important; 
  -webkit-backdrop-filter: blur(8px) saturate(120%) !important;

  /* 彻底干掉和票根打架的虚线边框！ */
  border: none !important;
  outline: none !important;

  /* 用极其温柔的弥散阴影在底部稍微托一下，增加层次感，而不是用线框死它 */
  box-shadow: 0 10px 30px var(--sq-ink-04) !important;
  border-radius: 12px !important; 
}


#sheld {
  top: var(--bottomFormBlockSize) !important;
  height: calc(100dvh - var(--bottomFormBlockSize)) !important;
  max-height: calc(100dvh - var(--bottomFormBlockSize)) !important;
  min-height: calc(100dvh - var(--bottomFormBlockSize)) !important;
  background: transparent !important;
}
#chat {
  background: transparent !important;
}

/* ----- 2. 顶栏 (强制通透) ----- */
body #top-bar,
body.no-blur #top-bar {
  background-color: var(--sq-page-35) !important;
  backdrop-filter: blur(8px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(8px) saturate(120%) !important;
  border: none !important;
  box-shadow: 0 4px 20px var(--sq-ink-05) !important;
}
/* 杀掉原版残留的顶栏遮罩 */
body #top-bar::after { display: none !important; }

/* ----- 3. 底栏输入框 (强制通透) ----- */
body #send_form,
body.no-blur #send_form {
  background-color: var(--sq-page-35) !important;
  backdrop-filter: blur(8px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(8px) saturate(120%) !important;
  border: none !important;
  box-shadow: 0 -4px 20px var(--sq-ink-05) !important;
}

/* ----- 2. 底栏悬浮化 (Send Form) ----- */
body #send_form,
body.no-blur #send_form {
  position: absolute !important; /* 关键：绝对定位脱离原本排版 */
  bottom: 0 !important;          /* 死死钉在最底部 */
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  z-index: 1000 !important;      /* 保证层级最高，不会被消息盖住 */

  /* 彻底干掉输入框顶部可能残留的自带边框 */
  border: none !important;
  border-top: none !important;
  margin: 0 !important;

  /* 强化底栏的毛玻璃效果，让穿透的文字更清晰 */
  background-color: var(--sq-page-35) !important;
  backdrop-filter: blur(12px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(12px) saturate(120%) !important;
}

body #chat,
body.no-blur #chat {
border: none !important;
  border-bottom: none !important;
  border-top: none !important;
}


