/* =========================================
   收官·修补：正则条目 (逻辑反转 + 边框加粗版)
   ========================================= */

/* 1. 开启状态（未勾选禁用，即正常运行）：深墨色文字 + 2px 暗金实线框 */
div.regex-script-label:not(:has(input[type="checkbox"]:checked)) {
  background: var(--sq-page-10) !important;
  border: 2px solid var(--sq-mid-60) !important; /* 加粗到 2px */
  border-radius: 8px !important;
  margin-bottom: 8px !important;
  transition: all 0.2s ease !important;
}
div.regex-script-label:not(:has(input[type="checkbox"]:checked)) span {
  color: var(--sq-deep) !important;
}

/* 2. 关闭状态（已勾选禁用，即划掉不生效）：半透明文字 + 2px 暗金虚线框 */
div.regex-script-label:has(input[type="checkbox"]:checked) {
  background: var(--sq-page-05) !important;
  border: 2px dashed var(--sq-mid-40) !important; /* 加粗到 2px */
  border-radius: 8px !important;
  margin-bottom: 8px !important;
  transition: all 0.2s ease !important;
}
div.regex-script-label:has(input[type="checkbox"]:checked) span {
  color: var(--sq-mid-60) !important;
}

/* 3. 操作图标：杀掉丑陋的按钮底色，换上复古暗金 */
div.regex-script-label .menu_button {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
div.regex-script-label .menu_button i,
div.regex-script-label .menu_button span::before {
  color: var(--sq-muted) !important; 
  -webkit-text-fill-color: var(--sq-muted) !important;
}

/* 悬停时图标点亮 */
div.regex-script-label .menu_button:hover i,
div.regex-script-label .menu_button:hover span::before {
  color: var(--sq-mid) !important;
  -webkit-text-fill-color: var(--sq-mid) !important;
}

/* =========================================
   修复3：Toast 提示弹窗 (极简复古便签+图标修复)
   ========================================= */

/* 清除可能导致翻车的旧样式 */
#toast-container > div::before, .toast::before,
#toast-container > div::after, .toast::after {
  display: none !important; 
  background-image: none !important;
}

/* 极简复古便签主体 */
#toast-container > div, .toast {
  background-color: var(--sq-cream) !important; /* 纸张底色 */
  color: var(--sq-deep) !important; 
  border: 1px solid var(--sq-mid-40) !important; /* 细边框 */
  border-left: 6px solid var(--sq-mid) !important; /* 左侧加粗暗金边，代替副券视觉 */
  border-radius: 4px !important;
  box-shadow: 0 4px 15px var(--sq-ink-08) !important;
  padding: 16px 20px !important;
}

/* 强行修复图标透明度与颜色 ( ✓ / × / ! ) */
.toast .toast_icon, 
.toast .fa-check, 
.toast .fa-times-circle, 
.toast .fa-exclamation-triangle {
  color: var(--sq-muted) !important; /* 统一改成暗金 */
  opacity: 1 !important; /* 满透明度 */
  -webkit-text-fill-color: var(--sq-muted) !important;
  font-size: 1.2em !important;
  margin-right: 8px !important;
}

/* 遇到报错时，左侧边条和图标变红 */
.toast-error { border-left-color: var(--sq-error) !important; }
.toast-error .toast_icon, .toast-error .fa-times-circle { 
  color: var(--sq-error) !important; 
  -webkit-text-fill-color: var(--sq-error) !important; 
}



