/* =========================================
   加载动画：心跳心电图（跟随主题色） (修复转圈Bug)
   ========================================= */

/* 1. 彻底杀掉父级的 360 度旋转动画，并隐藏原版齿轮 */
#load-spinner {
  animation: none !important; 
  transform: none !important;
  color: transparent !important; 
}

/* 隐藏聊天的三个小圆点 */
.mes_text .mes_loader span,
.typing_indicator span,
.mes_loader_new span {
  display: none !important;
}

/* 2. 注入心跳 SVG 动画 */
#load-spinner::before,
.mes_text .mes_loader::before,
.typing_indicator::before,
.mes_loader_new::before {
  content: "" !important;
  display: inline-block !important;
  width: 50px !important;
  height: 24px !important;
  margin-top: 4px !important;

  /* ⚠️ SVG 内的 stroke 色值需手动修改（URL编码格式：%23 + 六位色值） */
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 50"><polyline points="0,25 30,25 40,10 50,45 60,25 100,25" fill="none" stroke="%23b8a080" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>') !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;

  /* 仅让裁剪遮罩进行扫描动画，SVG本身不转 */
  animation: heartbeat_scan 1.4s linear infinite !important;
}

/* 3. 心跳动画关键帧 */
@keyframes heartbeat_scan {
  0% { clip-path: polygon(0 0, 0 100%, 0 100%, 0 0); filter: drop-shadow(0 0 2px var(--sq-mid-20)); }
  50% { clip-path: polygon(0 0, 0 100%, 100% 100%, 100% 0); filter: drop-shadow(0 0 6px var(--sq-mid-90)); }
  100% { clip-path: polygon(100% 0, 100% 100%, 100% 100%, 100% 0); filter: drop-shadow(0 0 2px var(--sq-mid-20)); }
}


